function story(title, description, crumb, h1, lede, sections, faq, links) {
  return {
    title,
    description,
    crumb,
    h1,
    lede,
    paragraphs: [lede],
    sections: sections.map(([heading, ...paragraphs]) => ({ heading, paragraphs })),
    faq,
    links,
  };
}

const link = (locale, pairs) => pairs;

const en = [["/crm", "CRM"], ["/pricing", "Pricing"], ["/guides", "Guides"], ["/contact", "Contact"]];
const he = [["/crm", "CRM"], ["/pricing", "מחירים"], ["/guides", "מדריכים"], ["/contact", "יצירת קשר"]];
const es = [["/crm", "CRM"], ["/pricing", "Precios"], ["/guides", "Guías"], ["/contact", "Contacto"]];
const pt = [["/crm", "CRM"], ["/pricing", "Preços"], ["/guides", "Guias"], ["/contact", "Contato"]];
const ar = [["/crm", "CRM"], ["/pricing", "الأسعار"], ["/guides", "الأدلة"], ["/contact", "اتصال"]];

function five(build) {
  return { en: build("en", en), he: build("he", he), es: build("es", es), "pt-BR": build("pt-BR", pt), ar: build("ar", ar) };
}

export const REST = {
  "/meta-campaigns": five((locale, links) => {
    const copy = {
      en: ["Meta Campaign Management for the work after the click | BizUply", "Edit Meta campaigns, ad sets and ads from the BizUply dashboard after the business connects its own ad account. Lead Ads can enter the CRM. Meta bills the spend. BizUply does not replace Ads Manager.", "Meta campaigns", "Campaign work that continues after the click", "A campaign is not finished when someone taps an ad. The useful question is what happens to the enquiry, and whether that person has a status and a next step.", ["From the ad to the enquiry", "A lead form on Facebook or Instagram can create a lead in BizUply, with its source, when the business has connected an eligible account and approved the permissions.", "The same six statuses used in the CRM apply: new, contacted, interested, converted, lost and old lead."], ["Work from one dashboard", "After the business connects its own Meta ad account, the dashboard can create and edit campaigns, ad sets and ads, with a budget at campaign or ad-set level.", "BizUply is a Meta Tech Provider and the app passed App Review for Lead Ads. That is not a claim that BizUply replaces Meta Ads Manager, and it is not a Meta Business Partner badge."], ["Campaigns and the CRM", "The lead keeps the source next to the contact details. The team updates the status, writes what happened, and opens a dated task. On the business plan, an automation can create that task for a new lead.", "The advertising invoice stays with Meta. There is no separate campaign price on this page. CRM only is $49 per month. The business plan is $99 per month or $990 per year."], ["Measurement that matches the daily work", "The dashboard shows results for the campaigns the business connected. It does not publish a private attribution model, and this page does not promise a return.", "Use the lead list to see which enquiries arrived, and the task list to see which of them still need a person."]],
      he: ["ניהול קמפיינים ב־Meta לעסקים | BizUply", "עורכים קמפיינים, קבוצות מודעות ומודעות של Meta מלוח הבקרה של BizUply אחרי שהעסק מחבר את חשבון המודעות שלו. לידים מטפסים יכולים להיכנס ל־CRM. את ההוצאה גובה Meta. BizUply לא מחליפה את Ads Manager.", "קמפיינים", "ניהול קמפיינים שממשיך אחרי הלחיצה", "קמפיין לא נגמר כשמישהו לוחץ על מודעה. השאלה המועילה היא מה קורה לפנייה, ואם לאדם הזה יש סטטוס וצעד הבא.", ["מהמודעה אל הפנייה", "טופס לידים בפייסבוק או באינסטגרם יכול ליצור ליד ב־BizUply, עם המקור שלו, אחרי שהעסק חיבר חשבון זכאי ואישר את ההרשאות.", "אותם שישה סטטוסים של ה־CRM חלים כאן: חדש, נוצר קשר, מעוניין, הומר, אבוד וליד ישן."], ["עבודה מלוח בקרה אחד", "אחרי שהעסק מחבר את חשבון המודעות שלו ב־Meta, אפשר ליצור ולערוך קמפיינים, קבוצות מודעות ומודעות, עם תקציב ברמת הקמפיין או הקבוצה.", "BizUply היא ספקית טכנולוגיה של Meta והאפליקציה עברה App Review ל־Lead Ads. זה לא אומר ש־BizUply מחליפה את Meta Ads Manager, וזה לא תג של Meta Business Partner."], ["קמפיינים ו־CRM", "הליד שומר את המקור ליד פרטי הקשר. הצוות מעדכן סטטוס, כותב מה קרה, ופותח משימה עם תאריך. בחבילה העסקית אוטומציה יכולה ליצור את המשימה לליד חדש.", "חשבונית הפרסום נשארת אצל Meta. אין מחיר נפרד לקמפיינים בעמוד הזה. CRM בלבד עולה 49 דולר לחודש. החבילה העסקית עולה 99 דולר לחודש או 990 דולר לשנה."], ["מדידה שמתחברת לעבודה היומית", "הלוח מציג תוצאות של הקמפיינים שהעסק חיבר. הוא לא מפרסם מודל ייחוס פרטי, והעמוד הזה לא מבטיח החזר.", "רשימת הלידים מראה אילו פניות נכנסו, ורשימת המשימות מראה אילו מהן עדיין מחכות לאדם."]],
      es: ["Gestión de campañas de Meta para el trabajo después del clic | BizUply", "Edite campañas, conjuntos y anuncios de Meta desde el panel de BizUply después de conectar la cuenta publicitaria del propio negocio. Los Lead Ads pueden entrar al CRM. Meta cobra el gasto. BizUply no sustituye a Ads Manager.", "Campañas", "El trabajo de campaña que sigue después del clic", "Una campaña no termina cuando alguien pulsa un anuncio. La pregunta útil es qué pasa con la consulta y si esa persona tiene un estado y un siguiente paso.", ["Del anuncio a la consulta", "Un formulario de clientes potenciales en Facebook o Instagram puede crear un lead en BizUply, con su origen, cuando el negocio conectó una cuenta elegible y aprobó los permisos.", "Sirven los mismos seis estados del CRM: nuevo, contactado, interesado, convertido, perdido y lead antiguo."], ["Trabajo desde un solo panel", "Después de conectar la propia cuenta de anuncios de Meta, el panel puede crear y editar campañas, conjuntos y anuncios, con presupuesto a nivel de campaña o de conjunto.", "BizUply es Tech Provider de Meta y la aplicación pasó App Review para Lead Ads. Eso no significa que BizUply sustituya a Meta Ads Manager, ni que sea Meta Business Partner."], ["Campañas y CRM", "El lead guarda el origen junto a los datos de contacto. El equipo actualiza el estado, anota lo que pasó y abre una tarea con fecha. En el plan de negocio, una automatización puede crear esa tarea para un lead nuevo.", "La factura publicitaria sigue en Meta. No hay un precio aparte de campañas en esta página. CRM solo cuesta 49 dólares al mes. El plan de negocio cuesta 99 dólares al mes o 990 al año."], ["Medición pegada al trabajo del día", "El panel muestra resultados de las campañas que el negocio conectó. No publica un modelo privado de atribución, y esta página no promete un retorno.", "La lista de leads muestra qué consultas llegaron. La lista de tareas muestra cuáles siguen esperando a una persona."]],
      "pt-BR": ["Gestão de campanhas da Meta para o trabalho depois do clique | BizUply", "Edite campanhas, conjuntos e anúncios da Meta no painel da BizUply depois que o negócio conecta a própria conta de anúncios. Lead Ads podem entrar no CRM. A Meta cobra o gasto. A BizUply não substitui o Ads Manager.", "Campanhas", "O trabalho de campanha continua depois do clique", "Uma campanha não termina quando alguém toca no anúncio. A pergunta útil é o que acontece com a consulta e se essa pessoa tem um status e um próximo passo.", ["Do anúncio para a consulta", "Um formulário de leads no Facebook ou no Instagram pode criar um lead na BizUply, com a origem, quando o negócio conectou uma conta elegível e aprovou as permissões.", "Valem os mesmos seis status do CRM: novo, contatado, interessado, convertido, perdido e lead antigo."], ["Trabalho num único painel", "Depois de conectar a própria conta de anúncios da Meta, o painel pode criar e editar campanhas, conjuntos e anúncios, com orçamento no nível da campanha ou do conjunto.", "A BizUply é Tech Provider da Meta e o aplicativo passou no App Review para Lead Ads. Isso não significa que a BizUply substitua o Meta Ads Manager, nem que seja Meta Business Partner."], ["Campanhas e CRM", "O lead guarda a origem ao lado dos dados de contato. A equipe atualiza o status, registra o que aconteceu e abre uma tarefa com data. No plano de negócios, uma automação pode criar essa tarefa para um lead novo.", "A fatura de mídia continua com a Meta. Não há preço separado de campanhas nesta página. O CRM sozinho custa 49 dólares por mês. O plano de negócios custa 99 dólares por mês ou 990 por ano."], ["Medição colada no trabalho do dia", "O painel mostra resultados das campanhas que o negócio conectou. Ele não publica um modelo privado de atribuição, e esta página não promete retorno.", "A lista de leads mostra quais consultas chegaram. A lista de tarefas mostra quais ainda esperam uma pessoa."]],
      ar: ["إدارة حملات Meta للعمل الذي يلي النقرة | BizUply", "حرّروا الحملات والمجموعات والإعلانات في لوحة BizUply بعد أن يربط النشاط حسابه الإعلاني. يمكن لنماذج Lead Ads أن تدخل CRM. تحصّل Meta الإنفاق. لا تحل BizUply محل Ads Manager.", "الحملات", "عمل الحملة يستمر بعد النقرة", "لا تنتهي الحملة حين يضغط أحد على الإعلان. السؤال المفيد هو ما الذي يحدث للاستفسار، وهل لهذا الشخص حالة وخطوة تالية.", ["من الإعلان إلى الاستفسار", "يمكن لنموذج عملاء محتملين على Facebook أو Instagram أن ينشئ عميلاً محتملاً في BizUply مع مصدره، بعد ربط حساب مؤهل والموافقة على الأذونات.", "تنطبق حالات CRM الست نفسها: جديد، تم التواصل، مهتم، تم التحويل، مفقود، وعميل محتمل قديم."], ["العمل من لوحة واحدة", "بعد ربط حساب Meta الإعلاني الخاص بالنشاط، يمكن للوحة إنشاء وتحرير الحملات والمجموعات والإعلانات، بميزانية على مستوى الحملة أو المجموعة.", "BizUply مزوّد تقني لدى Meta واجتاز التطبيق App Review لنماذج Lead Ads. هذا لا يعني أن BizUply تحل محل Meta Ads Manager، ولا أنها Meta Business Partner."], ["الحملات وCRM", "يحتفظ العميل المحتمل بالمصدر إلى جانب بيانات الاتصال. يحدّث الفريق الحالة، ويكتب ما حدث، ويفتح مهمة بتاريخ. في الخطة التجارية يمكن للأتمتة أن تنشئ هذه المهمة لعميل محتمل جديد.", "تبقى فاتورة الإعلان عند Meta. لا يوجد سعر منفصل للحملات في هذه الصفحة. CRM وحده 49 دولاراً شهرياً. الخطة التجارية 99 دولاراً شهرياً أو 990 سنوياً."], ["قياس ملتصق بالعمل اليومي", "تعرض اللوحة نتائج الحملات التي ربطها النشاط. لا تنشر نموذج إسناد خاصاً، وهذه الصفحة لا تعد بعائد.", "تعرض قائمة العملاء المحتملين الاستفسارات التي وصلت. تعرض قائمة المهام ما الذي ما زال ينتظر شخصاً."]],
    }[locale];
    const [title, description, crumb, h1, lede, ...sections] = copy;
    return story(title, description, crumb, h1, lede, sections, locale === "he"
      ? [["מהו קמפיין Meta?", "קמפיין פרסום שמנוהל במערכות הפרסום של Meta, כולל מיקומים נתמכים כמו Facebook ו־Instagram."], ["למה לחבר קמפיין ל־CRM?", "כדי שהפנייה לא תישאר בדוח של המודעה בלבד. המקור, הסטטוס והמשימה נשמרים על אותו ליד."], ["האם BizUply מחליפה את Meta Ads Manager?", "לא. אפשר ליצור ולערוך קמפיינים מתוך הלוח אחרי חיבור החשבון. Meta נשארת המערכת שמפיצה את המודעות ומחייבת את ההוצאה."], ["האם תקציב הפרסום כלול במחיר המערכת?", "לא. תקציב המדיה וחיוב Meta נפרדים ממחיר CRM או מהחבילה העסקית."]]
      : locale === "es"
        ? [["¿Qué es una campaña de Meta?", "Es una campaña que se gestiona en los sistemas de publicidad de Meta, incluidos espacios como Facebook e Instagram."], ["¿Por qué conectar la campaña al CRM?", "Para que la consulta no se quede solo en el informe del anuncio. El origen, el estado y la tarea quedan en el mismo lead."], ["¿BizUply sustituye a Meta Ads Manager?", "No. Se pueden crear y editar campañas desde el panel después de conectar la cuenta. Meta sigue entregando los anuncios y cobrando el gasto."], ["¿El presupuesto publicitario está incluido?", "No. El presupuesto y la factura de Meta son independientes del precio del CRM o del plan de negocio."]]
        : locale === "pt-BR"
          ? [["O que é uma campanha da Meta?", "É uma campanha gerida nos sistemas de anúncio da Meta, incluindo espaços como Facebook e Instagram."], ["Por que ligar a campanha ao CRM?", "Para a consulta não ficar só no relatório do anúncio. A origem, o status e a tarefa ficam no mesmo lead."], ["A BizUply substitui o Meta Ads Manager?", "Não. Dá para criar e editar campanhas no painel depois de conectar a conta. A Meta continua entregando os anúncios e cobrando o gasto."], ["A verba de mídia está inclusa?", "Não. A verba e a cobrança da Meta são independentes do preço do CRM ou do plano de negócios."]]
          : locale === "ar"
            ? [["ما هي حملة Meta؟", "حملة تُدار في أنظمة إعلانات Meta، بما في ذلك مواضع مثل Facebook وInstagram."], ["لماذا نربط الحملة بـ CRM؟", "لكي لا يبقى الاستفسار في تقرير الإعلان فقط. يبقى المصدر والحالة والمهمة على العميل المحتمل نفسه."], ["هل تحل BizUply محل Meta Ads Manager؟", "لا. يمكن إنشاء الحملات وتحريرها من اللوحة بعد ربط الحساب. تبقى Meta النظام الذي يعرض الإعلانات ويحصّل الإنفاق."], ["هل ميزانية الإعلان مشمولة؟", "لا. ميزانية الوسيلة وفاتورة Meta منفصلتان عن سعر CRM أو الخطة التجارية."]]
            : [["What is a Meta campaign?", "An ad campaign managed in Meta's advertising systems, including placements such as Facebook and Instagram."], ["Why connect a campaign to the CRM?", "So the enquiry is not left only in the ad report. The source, the status and the task stay on the same lead."], ["Does BizUply replace Meta Ads Manager?", "No. Campaigns can be created and edited from the dashboard after the account is connected. Meta still delivers the ads and bills the spend."], ["Is the ad budget included in the software price?", "No. Media budget and Meta's invoice are separate from the CRM price and from the business plan."]], links);
  }),
  "/website-builder": five((locale, links) => {
    const copy = {
      en: ["Business websites and stores | BizUply", "Build a site in the BizUply visual editor and publish it to your address. A supported form on that site can create a lead in the CRM. The site has its own price on the pricing page. A template count is not published here.", "Websites", "A business website that joins the work of the business", "A site is where someone learns what you offer and leaves a way to reply. The BizUply editor is for that presence, and a supported form can hand the enquiry to the CRM.", ["The site is part of the work, not only a card", "The page should say what the business does, who it is for, and what the visitor can do next. The editor changes the content in place. This page does not publish a number of templates, because that count is not being restated from an old list.", "A store can be added where that option is available in the editor. A store is not assumed for every site."], ["Editing that follows the brand", "Text, images and the blocks the editor exposes can be changed for the business. What you cannot find in the editor is not promised on this page.", "Professional setup, when you want someone else to do the build, is a separate service and a separate price."], ["Reading on a phone", "The published sites are meant to be read on a computer, a tablet and a phone. Check the actual page after publishing. This page does not attach a lab score to every template."], ["A form that can become a lead", "A supported form on a BizUply site can create a lead with the website as its source. The lead then uses the same statuses, notes and tasks as any other lead.", "The connection exists when the form and the CRM are both active on the account. It is not a hidden extra product."]],
      he: ["בניית אתרים עסקיים וחנויות | BizUply", "בונים אתר בעורך החזותי של BizUply ומפרסמים אותו לכתובת שלכם. טופס נתמך באתר יכול ליצור ליד ב־CRM. לאתר מחיר משלו בעמוד המחירים. מספר התבניות לא מפורסם כאן.", "אתרים", "אתר עסקי שמתחבר לעבודה של העסק", "אתר הוא המקום שבו מישהו לומד מה העסק מציע ומשאיר דרך לחזור אליו. העורך של BizUply מיועד לנוכחות הזו, וטופס נתמך יכול להעביר את הפנייה ל־CRM.", ["האתר הוא חלק מהעבודה, לא רק כרטיס ביקור", "העמוד צריך לומר מה העסק עושה, למי הוא מיועד, ומה המבקר יכול לעשות עכשיו. העורך משנה את התוכן במקום. העמוד הזה לא מפרסם מספר תבניות, כי אין כאן ספירה מחדש של רשימה ישנה.", "אפשר להוסיף חנות כשהאפשרות הזו קיימת בעורך. חנות לא נכללת אוטומטית בכל אתר."], ["עריכה שמתאימה למותג", "אפשר לשנות טקסט, תמונות והבלוקים שהעורך חושף. מה שלא נמצא בעורך לא מובטח בעמוד הזה.", "הקמה מקצועית, כשמישהו אחר בונה את האתר, היא שירות נפרד ובמחיר נפרד."], ["קריאה בטלפון", "האתרים שמתפרסמים נועדו להיקרא במחשב, בטאבלט ובטלפון. בודקים את העמוד עצמו אחרי הפרסום. העמוד הזה לא מצמיד ציון מעבדה לכל תבנית."], ["טופס שיכול להפוך לליד", "טופס נתמך באתר BizUply יכול ליצור ליד שהמקור שלו הוא האתר. אחר כך הליד משתמש באותם סטטוסים, הערות ומשימות כמו כל ליד אחר.", "החיבור קיים כשהטופס וה־CRM פעילים בחשבון. זה לא מוצר נסתר נוסף."]],
      es: ["Sitios de negocio y tiendas | BizUply", "Cree un sitio en el editor visual de BizUply y publíquelo en su dirección. Un formulario compatible puede crear un lead en el CRM. El sitio tiene su propio precio en la página de precios. Aquí no se publica un número de plantillas.", "Sitios", "Un sitio de negocio que se une al trabajo del negocio", "Un sitio es el lugar donde alguien entiende qué ofrece usted y deja una forma de responder. El editor de BizUply sirve para esa presencia, y un formulario compatible puede pasar la consulta al CRM.", ["El sitio es parte del trabajo, no solo una tarjeta", "La página debe decir qué hace el negocio, para quién es y qué puede hacer el visitante ahora. El editor cambia el contenido en el lugar. Esta página no publica un número de plantillas, porque no hay un recuento nuevo de una lista vieja.", "Se puede añadir una tienda cuando esa opción existe en el editor. Una tienda no viene incluida en todos los sitios."], ["Edición que sigue a la marca", "Se cambian textos, imágenes y los bloques que el editor muestra. Lo que no está en el editor no se promete en esta página.", "La puesta en marcha profesional, cuando otra persona construye el sitio, es un servicio aparte y un precio aparte."], ["Lectura en el teléfono", "Los sitios publicados están pensados para leerse en un ordenador, una tableta y un teléfono. Revise la página real después de publicar. Esta página no adjunta una nota de laboratorio a cada plantilla."], ["Un formulario que puede volverse un lead", "Un formulario compatible en un sitio de BizUply puede crear un lead cuyo origen es el sitio. Después el lead usa los mismos estados, notas y tareas que cualquier otro lead.", "La conexión existe cuando el formulario y el CRM están activos en la cuenta. No es un producto oculto."]],
      "pt-BR": ["Sites de negócio e lojas | BizUply", "Crie um site no editor visual da BizUply e publique no seu endereço. Um formulário compatível pode criar um lead no CRM. O site tem o próprio preço na página de preços. Um número de modelos não é publicado aqui.", "Sites", "Um site de negócio que entra no trabalho do negócio", "Um site é o lugar em que alguém entende o que você oferece e deixa um jeito de responder. O editor da BizUply serve a essa presença, e um formulário compatível pode passar a consulta ao CRM.", ["O site faz parte do trabalho, não só um cartão", "A página precisa dizer o que o negócio faz, para quem é e o que o visitante pode fazer agora. O editor muda o conteúdo no lugar. Esta página não publica um número de modelos, porque não há uma nova contagem de uma lista antiga.", "Dá para acrescentar uma loja quando essa opção existe no editor. Uma loja não vem incluída em todo site."], ["Edição que acompanha a marca", "Mudam-se textos, imagens e os blocos que o editor mostra. O que não está no editor não é prometido nesta página.", "A montagem profissional, quando outra pessoa constrói o site, é um serviço separado e um preço separado."], ["Leitura no telefone", "Os sites publicados são feitos para serem lidos no computador, no tablet e no telefone. Confira a página real depois de publicar. Esta página não cola uma nota de laboratório em cada modelo."], ["Um formulário que pode virar lead", "Um formulário compatível num site da BizUply pode criar um lead cuja origem é o site. Depois o lead usa os mesmos status, notas e tarefas de qualquer outro lead.", "A conexão existe quando o formulário e o CRM estão ativos na conta. Não é um produto escondido."]],
      ar: ["مواقع أعمال ومتاجر | BizUply", "ابنوا موقعاً في المحرر البصري لدى BizUply وانشروه على عنوانكم. يمكن لنموذج مدعوم أن ينشئ عميلاً محتملاً في CRM. للموقع سعره في صفحة الأسعار. لا يُنشر هنا عدد القوالب.", "المواقع", "موقع عمل ينضم إلى عمل النشاط", "الموقع هو المكان الذي يفهم فيه الزائر ما يقدّمه النشاط ويترك طريقة للرد. محرر BizUply مخصص لهذا الحضور، ويمكن لنموذج مدعوم أن ينقل الاستفسار إلى CRM.", ["الموقع جزء من العمل، وليس بطاقة فقط", "يجب أن تقول الصفحة ماذا يفعل النشاط، ولمن هو، وما الذي يستطيع الزائر فعله الآن. يغيّر المحرر المحتوى في مكانه. لا تنشر هذه الصفحة عدد القوالب، لأنه لا توجد إعادة عدّ لقائمة قديمة.", "يمكن إضافة متجر حين يكون هذا الخيار موجوداً في المحرر. المتجر ليس مشمولاً تلقائياً في كل موقع."], ["تحرير يتبع العلامة", "يمكن تغيير النصوص والصور والكتل التي يعرضها المحرر. ما لا يوجد في المحرر لا يُوعد به في هذه الصفحة.", "الإعداد المهني، حين يبني شخص آخر الموقع، خدمة منفصلة وبسعر منفصل."], ["القراءة على الهاتف", "المواقع المنشورة معدة للقراءة على الحاسوب والجهاز اللوحي والهاتف. راجعوا الصفحة الفعلية بعد النشر. لا تلصق هذه الصفحة درجة مخبرية بكل قالب."], ["نموذج يمكن أن يصبح عميلاً محتملاً", "يمكن لنموذج مدعوم في موقع BizUply أن ينشئ عميلاً محتملاً مصدره الموقع. بعدها يستخدم العميل الحالات والملاحظات والمهام نفسها كأي عميل آخر.", "يوجد الربط حين يكون النموذج وCRM نشطين في الحساب. ليس منتجاً خفياً."]],
    }[locale];
    const [title, description, crumb, h1, lede, ...sections] = copy;
    const faq = {
      en: [["What is the difference between a brochure site and a store?", "A brochure site presents the business and a way to enquire. A store also presents products and a purchase path, where that option is available in the editor."], ["Can a form create a CRM lead?", "Yes, when the supported form and the CRM are both active. The lead keeps the website as its source."], ["Does the site work on a phone?", "The published sites are meant to be read on a phone. Check the page you published. This page does not attach a score to every template."], ["Are the domain and hosting included?", "Do not assume that. The site has its own price on the pricing page. Domain and hosting terms are whatever that page and the account actually show."]],
      he: [["מה ההבדל בין אתר תדמית לחנות?", "אתר תדמית מציג את העסק ודרך לפנייה. חנות מציגה גם מוצרים ומסלול רכישה, כשהאפשרות הזו קיימת בעורך."], ["האם טופס יכול ליצור ליד ב־CRM?", "כן, כשהטופס הנתמך וה־CRM פעילים. הליד שומר את האתר כמקור."], ["האם האתר נקרא בטלפון?", "האתרים שמתפרסמים נועדו להיקרא בטלפון. בודקים את העמוד שפרסמתם. העמוד הזה לא מצמיד ציון לכל תבנית."], ["האם דומיין ואחסון כלולים?", "אין להניח שכן. לאתר מחיר משלו בעמוד המחירים. תנאי הדומיין והאחסון הם מה שהעמוד והחשבון מציגים בפועל."]],
      es: [["¿Qué diferencia hay entre un sitio de presentación y una tienda?", "El sitio de presentación muestra el negocio y una forma de consultar. La tienda también muestra productos y un camino de compra, cuando esa opción existe en el editor."], ["¿Un formulario puede crear un lead en el CRM?", "Sí, cuando el formulario compatible y el CRM están activos. El lead guarda el sitio como origen."], ["¿El sitio se lee en el teléfono?", "Los sitios publicados están pensados para leerse en el teléfono. Revise la página que publicó. Esta página no pone una nota a cada plantilla."], ["¿El dominio y el alojamiento están incluidos?", "No hay que suponerlo. El sitio tiene su precio en la página de precios. Las condiciones de dominio y alojamiento son las que muestran esa página y la cuenta."]],
      "pt-BR": [["Qual é a diferença entre um site institucional e uma loja?", "O site institucional apresenta o negócio e um jeito de consultar. A loja também apresenta produtos e um caminho de compra, quando essa opção existe no editor."], ["Um formulário pode criar um lead no CRM?", "Sim, quando o formulário compatível e o CRM estão ativos. O lead guarda o site como origem."], ["O site é lido no telefone?", "Os sites publicados são feitos para serem lidos no telefone. Confira a página que você publicou. Esta página não cola uma nota em cada modelo."], ["Domínio e hospedagem estão inclusos?", "Não dá para supor isso. O site tem o próprio preço na página de preços. As condições de domínio e hospedagem são as que essa página e a conta mostram."]],
      ar: [["ما الفرق بين موقع تعريفي ومتجر؟", "الموقع التعريفي يعرض النشاط وطريقة للاستفسار. المتجر يعرض أيضاً منتجات ومسار شراء، حين يكون هذا الخيار موجوداً في المحرر."], ["هل يمكن لنموذج أن ينشئ عميلاً محتملاً في CRM؟", "نعم، حين يكون النموذج المدعوم وCRM نشطين. يحتفظ العميل بالموقع كمصدر."], ["هل يُقرأ الموقع على الهاتف؟", "المواقع المنشورة معدة للقراءة على الهاتف. راجعوا الصفحة التي نشرتموها. لا تضع هذه الصفحة درجة لكل قالب."], ["هل النطاق والاستضافة مشمولان؟", "لا تفترضوا ذلك. للموقع سعره في صفحة الأسعار. شروط النطاق والاستضافة هي ما تعرضه تلك الصفحة والحساب فعلاً."]],
    }[locale];
    return story(title, description, crumb, h1, lede, sections, faq, links);
  }),
  "/appointments": five((locale, links) => {
    const copy = {
      en: ["Appointments and bookings for businesses | BizUply", "BizUply appointments set business hours, a service catalog with duration and price, and 15-minute openings. A customer can book on a public page. Appointments belong to the business plan, not to CRM only at $49 per month.", "Appointments", "The day's appointments in one calendar", "A service business needs to see who is coming, for which service, and at what time. BizUply keeps that calendar next to the customer record on the business plan.", ["A calendar the team can read", "You set hours for each day of the week. The calendar builds openings from those hours and from the length of the service, in steps of 15 minutes.", "Each appointment stores the service, the price, a payment status and a note. A payment status is a field on the appointment. It is not a claim that the card is charged automatically."], ["The appointment stays with the customer", "The booking is tied to the customer, so the next person who opens the record can see the service and the time without searching another tool.", "When a customer books on the public page, a confirmation email goes to the customer and to the business, and the appointment shows on the calendar."], ["Availability is a setting, not a guess", "The openings come from the hours and the service length you entered. If the hours are wrong, the openings are wrong. Change the hours and the catalog in the account.", "Online booking by the customer is part of the business plan. It is not included in CRM only."], ["Services and the price on the appointment", "The catalog holds the service, how long it takes, and its price. That price is what the appointment records. Collecting the money is a separate step unless the account already has a payment flow you have turned on.", "Upcoming appointments also appear on the business dashboard, next to new and untreated leads."]],
      he: ["מערכת לניהול פגישות ותורים לעסקים | BizUply", "התורים של BizUply מגדירים שעות פעילות, קטלוג שירותים עם משך ומחיר, וחלונות של 15 דקות. לקוח יכול לקבוע בעמוד ציבורי. התורים שייכים לחבילה העסקית, לא ל־CRM בלבד ב־49 דולר לחודש.", "תורים", "כל הפגישות והתורים של העסק במקום אחד", "עסק שירות צריך לראות מי מגיע, לאיזה שירות, ובאיזו שעה. BizUply שומרת את היומן הזה ליד רשומת הלקוח בחבילה העסקית.", ["יומן שהצוות יכול לקרוא", "מגדירים שעות לכל יום בשבוע. היומן בונה חלונות מהשעות האלה ומאורך השירות, בקפיצות של 15 דקות.", "כל תור שומר שירות, מחיר, סטטוס תשלום והערה. סטטוס תשלום הוא שדה על התור. זו לא טענה שהכרטיס מחויב אוטומטית."], ["התור נשאר עם הלקוח", "ההזמנה קשורה ללקוח, כך שהאדם הבא שפותח את הרשומה רואה את השירות ואת השעה בלי לחפש בכלי אחר.", "כשלקוח קובע בעמוד הציבורי, נשלח אישור במייל ללקוח ולעסק, והתור מופיע ביומן."], ["הזמינות היא הגדרה, לא ניחוש", "החלונות נוצרים מהשעות ומאורך השירות שהזנתם. אם השעות שגויות, גם החלונות שגויים. משנים את השעות ואת הקטלוג בחשבון.", "זימון על ידי הלקוח הוא חלק מהחבילה העסקית. הוא לא כלול ב־CRM בלבד."], ["שירותים והמחיר על התור", "הקטלוג שומר את השירות, כמה זמן הוא נמשך, ומה מחירו. המחיר הזה הוא מה שהתור רושם. גביית הכסף היא צעד נפרד, אלא אם בחשבון כבר פועל מסלול תשלום שהפעלתם.", "תורים קרובים מופיעים גם בלוח הבקרה של העסק, ליד לידים חדשים ולידים שלא טופלו."]],
      es: ["Citas y reservas para negocios | BizUply", "Las citas de BizUply definen horarios, un catálogo de servicios con duración y precio, y huecos de 15 minutos. Un cliente puede reservar en una página pública. Las citas pertenecen al plan de negocio, no a CRM solo de 49 dólares al mes.", "Citas", "Las citas del día en un solo calendario", "Un negocio de servicios necesita ver quién llega, para qué servicio y a qué hora. BizUply guarda ese calendario junto a la ficha del cliente en el plan de negocio.", ["Un calendario que el equipo puede leer", "Se definen horarios para cada día de la semana. El calendario arma huecos a partir de esos horarios y de la duración del servicio, en pasos de 15 minutos.", "Cada cita guarda el servicio, el precio, un estado de pago y una nota. El estado de pago es un campo de la cita. No es una afirmación de que la tarjeta se cobre sola."], ["La cita se queda con el cliente", "La reserva está unida al cliente, así que la siguiente persona que abre la ficha ve el servicio y la hora sin buscar en otra herramienta.", "Cuando un cliente reserva en la página pública, se envía un correo de confirmación al cliente y al negocio, y la cita aparece en el calendario."], ["La disponibilidad es un ajuste, no una suposición", "Los huecos salen de los horarios y de la duración que usted cargó. Si los horarios están mal, los huecos también. Se cambian en la cuenta.", "La reserva en línea por el cliente forma parte del plan de negocio. No está incluida en CRM solo."], ["Servicios y el precio en la cita", "El catálogo guarda el servicio, cuánto dura y cuál es su precio. Ese precio es el que registra la cita. Cobrar el dinero es un paso aparte, salvo que la cuenta ya tenga un flujo de pago activado.", "Las próximas citas también aparecen en el panel del negocio, junto a los leads nuevos y los que siguen sin tratar."]],
      "pt-BR": ["Agenda de horários e reservas para negócios | BizUply", "A agenda da BizUply define horários de funcionamento, um catálogo de serviços com duração e preço, e vagas de 15 minutos. O cliente pode reservar numa página pública. A agenda pertence ao plano de negócios, não ao CRM sozinho de 49 dólares por mês.", "Agenda", "Os horários do dia num único calendário", "Um negócio de serviço precisa ver quem chega, para qual serviço e a que hora. A BizUply guarda esse calendário ao lado da ficha do cliente no plano de negócios.", ["Um calendário que a equipe consegue ler", "Definem-se horários para cada dia da semana. O calendário monta vagas a partir desses horários e da duração do serviço, em passos de 15 minutos.", "Cada horário guarda o serviço, o preço, um status de pagamento e uma nota. O status de pagamento é um campo do horário. Não é uma afirmação de que o cartão é cobrado sozinho."], ["O horário fica com o cliente", "A reserva está ligada ao cliente, então a próxima pessoa que abre a ficha vê o serviço e a hora sem procurar em outra ferramenta.", "Quando o cliente reserva na página pública, um e-mail de confirmação vai para o cliente e para o negócio, e o horário aparece no calendário."], ["A disponibilidade é um ajuste, não um palpite", "As vagas saem dos horários e da duração que você cadastrou. Se os horários estiverem errados, as vagas também estarão. A mudança é feita na conta.", "A reserva online pelo cliente faz parte do plano de negócios. Não está incluída no CRM sozinho."], ["Serviços e o preço no horário", "O catálogo guarda o serviço, quanto tempo dura e qual é o preço. Esse preço é o que o horário registra. Receber o dinheiro é um passo separado, salvo se a conta já tiver um fluxo de pagamento ligado.", "Os próximos horários também aparecem no painel do negócio, ao lado dos leads novos e dos que ainda não foram tratados."]],
      ar: ["مواعيد وحجوزات للأعمال | BizUply", "تحدد مواعيد BizUply ساعات العمل، وكتالوج خدمات بالمدة والسعر، وفتحات من 15 دقيقة. يمكن للعميل الحجز في صفحة عامة. المواعيد تابعة للخطة التجارية، لا لـ CRM وحده بسعر 49 دولاراً شهرياً.", "المواعيد", "مواعيد اليوم في تقويم واحد", "يحتاج نشاط الخدمات إلى معرفة من سيصل، ولأي خدمة، وفي أي ساعة. تحفظ BizUply هذا التقويم إلى جانب سجل العميل في الخطة التجارية.", ["تقويم يستطيع الفريق قراءته", "تُضبط ساعات كل يوم من أيام الأسبوع. يبني التقويم الفتحات من هذه الساعات ومن مدة الخدمة، بخطوات من 15 دقيقة.", "يحفظ كل موعد الخدمة والسعر وحالة الدفع وملاحظة. حالة الدفع حقل على الموعد. ليست ادّعاءً بأن البطاقة تُحصَّل تلقائياً."], ["يبقى الموعد مع العميل", "يرتبط الحجز بالعميل، فيرى الشخص التالي الذي يفتح السجل الخدمة والساعة من دون البحث في أداة أخرى.", "حين يحجز العميل في الصفحة العامة، تُرسل رسالة تأكيد بالبريد إلى العميل وإلى النشاط، ويظهر الموعد في التقويم."], ["التوفر إعداد وليس تخميناً", "تأتي الفتحات من الساعات ومن مدة الخدمة التي أدخلتموها. إذا كانت الساعات خاطئة فالفتحات خاطئة. يُغيَّر ذلك في الحساب.", "الحجز عبر الإنترنت من قبل العميل جزء من الخطة التجارية. ليس مشمولاً في CRM وحده."], ["الخدمات والسعر على الموعد", "يحفظ الكتالوج الخدمة ومدة تنفيذها وسعرها. هذا السعر هو ما يسجله الموعد. تحصيل المال خطوة منفصلة، إلا إذا كان في الحساب مسار دفع شغّلتموه.", "تظهر المواعيد القادمة أيضاً في لوحة النشاط، إلى جانب العملاء المحتملين الجدد والذين لم يُعالجوا."]],
    }[locale];
    const [title, description, crumb, h1, lede, ...sections] = copy;
    const faq = {
      en: [["What is an appointment system?", "Software that organizes services, hours, openings and the customer attached to each booking."], ["Who is it for?", "Businesses that meet customers by appointment: services, clinics that are not using it as a medical record, consultants and similar work. It is not a clinical records system."], ["Can we see what is coming up?", "Yes. The calendar lists the bookings, and the business dashboard shows upcoming appointments."], ["Are appointments included with CRM only?", "No. Appointments and customer booking belong to the business plan, at $99 per month or $990 per year. CRM only is the pipeline at $49 per month."]],
      he: [["מהי מערכת לניהול תורים?", "תוכנה שמארגנת שירותים, שעות, חלונות פנויים ואת הלקוח שמקושר לכל הזמנה."], ["למי היא מתאימה?", "לעסקים שנפגשים עם לקוחות לפי תור: שירותים, קליניקות שלא משתמשות בה כרשומה רפואית, יועצים ועבודה דומה. זו לא מערכת רשומות רפואיות."], ["אפשר לראות מה מתוכנן?", "כן. היומן מציג את ההזמנות, ולוח הבקרה של העסק מציג תורים קרובים."], ["האם התורים כלולים ב־CRM בלבד?", "לא. תורים וזימון על ידי הלקוח שייכים לחבילה העסקית, ב־99 דולר לחודש או 990 דולר לשנה. CRM בלבד הוא הצינור ב־49 דולר לחודש."]],
      es: [["¿Qué es un sistema de citas?", "Un software que organiza servicios, horarios, huecos y el cliente unido a cada reserva."], ["¿Para quién sirve?", "Para negocios que reciben clientes con cita: servicios, clínicas que no la usan como historia clínica, consultores y trabajos parecidos. No es un sistema de historia clínica."], ["¿Se puede ver lo que viene?", "Sí. El calendario muestra las reservas y el panel del negocio muestra las próximas citas."], ["¿Las citas están incluidas en CRM solo?", "No. Las citas y la reserva del cliente pertenecen al plan de negocio, a 99 dólares al mes o 990 al año. CRM solo es el pipeline a 49 dólares al mes."]],
      "pt-BR": [["O que é um sistema de agenda?", "Um software que organiza serviços, horários, vagas e o cliente ligado a cada reserva."], ["Para quem serve?", "Para negócios que recebem clientes com hora marcada: serviços, clínicas que não a usam como prontuário, consultores e trabalhos parecidos. Não é um sistema de prontuário."], ["Dá para ver o que vem pela frente?", "Sim. O calendário mostra as reservas e o painel do negócio mostra os próximos horários."], ["A agenda está inclusa no CRM sozinho?", "Não. A agenda e a reserva pelo cliente pertencem ao plano de negócios, a 99 dólares por mês ou 990 por ano. O CRM sozinho é o funil a 49 dólares por mês."]],
      ar: [["ما هو نظام المواعيد؟", "برنامج ينظّم الخدمات والساعات والفتحات والعميل المرتبط بكل حجز."], ["لمن يناسب؟", "للأنشطة التي تستقبل العملاء بموعد: خدمات، وعيادات لا تستخدمه كسجل طبي، ومستشارون وأعمال مشابهة. ليس نظام سجلات طبية."], ["هل يمكن رؤية ما هو قادم؟", "نعم. يعرض التقويم الحجوزات، وتعرض لوحة النشاط المواعيد القادمة."], ["هل المواعيد مشمولة في CRM وحده؟", "لا. المواعيد وحجز العميل تابعان للخطة التجارية، بسعر 99 دولاراً شهرياً أو 990 سنوياً. CRM وحده هو المسار بسعر 49 دولاراً شهرياً."]],
    }[locale];
    return story(title, description, crumb, h1, lede, sections, faq, links);
  }),
  "/agents": five((locale, links) => {
    const copy = {
      en: ["Human agents for leads and follow-up | BizUply", "BizUply agents on this page are people, not a chatbot. They handle defined follow-up on leads, details and meetings according to the service that was actually purchased. No reply rate or sales rate is promised.", "Agents", "When the business needs a person to continue the enquiry", "A form does not finish every enquiry. Sometimes someone has to call, clarify, or set a time. The agents service is that human layer, inside the limits of the plan you buy.", ["A person on the enquiry", "The agent works the lead the business assigned: reads what arrived, asks what is missing, and writes the result back on the record.", "This page does not describe an AI chatbot. If a screen elsewhere mentions an assistant, that is a different tool."], ["Following up while the lead is still warm", "The work is the next contact, not a promise that the person will buy. The agent uses the same statuses the CRM already has, so the team can see whether contact was made.", "There is no published conversion rate on this page, and none should be inferred."], ["Meetings, when the service includes them", "If the purchased service includes setting an appointment, the agent can place it on the calendar the account already uses. If the service does not include that, the page does not add it.", "The current scope is whatever the pricing page and the agreement say. This page does not invent a package price."], ["The note stays in the CRM", "A call that is not written down disappears. The point of the service is that the outcome is recorded on the lead: what was said, the status, and the next task.", "The agent's access follows the roles on the business account. This page does not create a new permission model."]],
      he: ["נציגים אנושיים לטיפול בלידים ובפניות | BizUply", "הנציגים בעמוד הזה הם אנשים, לא צ'אטבוט. הם מטפלים במעקב מוגדר אחרי לידים, בפרטים ובפגישות לפי השירות שנרכש בפועל. אין כאן הבטחה לשיעור מענה או לשיעור מכירה.", "נציגים", "כשהעסק צריך אדם שימשיך את הטיפול בפנייה", "טופס לא מסיים כל פנייה. לפעמים צריך להתקשר, להבהיר, או לקבוע שעה. שירות הנציגים הוא השכבה האנושית הזו, בגבולות המסלול שקונים.", ["אדם על הפנייה", "הנציג עובד על הליד שהעסק שייך: קורא מה נכנס, שואל מה חסר, ורושם את התוצאה בחזרה על הרשומה.", "העמוד הזה לא מתאר צ'אטבוט. אם מסך אחר מזכיר עוזר, זה כלי אחר."], ["המשך טיפול כל עוד הפנייה חיה", "העבודה היא הקשר הבא, לא הבטחה שהאדם יקנה. הנציג משתמש באותם סטטוסים שכבר יש ב־CRM, כדי שהצוות יראה אם נוצר קשר.", "אין בעמוד הזה שיעור המרה מפורסם, ואין להסיק אחד."], ["פגישות, כשהשירות כולל אותן", "אם השירות שנרכש כולל קביעת תור, הנציג יכול להניח אותו על היומן שהחשבון כבר משתמש בו. אם השירות לא כולל זאת, העמוד לא מוסיף את זה.", "ההיקף העדכני הוא מה שעמוד המחירים וההסכם אומרים. העמוד הזה לא ממציא מחיר לחבילה."], ["התיעוד נשאר ב־CRM", "שיחה שלא נכתבת נעלמת. הטעם של השירות הוא שהתוצאה נרשמת על הליד: מה נאמר, הסטטוס, והמשימה הבאה.", "הגישה של הנציג עוקבת אחרי התפקידים בחשבון העסק. העמוד הזה לא יוצר מודל הרשאות חדש."]],
      es: ["Agentes humanos para leads y seguimiento | BizUply", "Los agentes de esta página son personas, no un chatbot. Hacen el seguimiento definido de leads, datos y citas según el servicio que de verdad se compró. No se promete una tasa de respuesta ni de venta.", "Agentes", "Cuando el negocio necesita a una persona para seguir con la consulta", "Un formulario no cierra todas las consultas. A veces hay que llamar, aclarar o fijar una hora. El servicio de agentes es esa capa humana, dentro de los límites del plan que se compra.", ["Una persona sobre la consulta", "El agente trabaja el lead que el negocio asignó: lee lo que llegó, pregunta lo que falta y escribe el resultado en la ficha.", "Esta página no describe un chatbot. Si otra pantalla menciona un asistente, es otra herramienta."], ["Seguimiento mientras la consulta sigue viva", "El trabajo es el siguiente contacto, no una promesa de que la persona compre. El agente usa los mismos estados que ya tiene el CRM, para que el equipo vea si hubo contacto.", "En esta página no hay una tasa de conversión publicada, y no hay que deducir una."], ["Citas, cuando el servicio las incluye", "Si el servicio comprado incluye fijar una cita, el agente puede colocarla en el calendario que la cuenta ya usa. Si el servicio no lo incluye, esta página no lo añade.", "El alcance actual es el que dicen la página de precios y el acuerdo. Esta página no inventa un precio de paquete."], ["La nota se queda en el CRM", "Una llamada que no se escribe desaparece. El sentido del servicio es que el resultado quede en el lead: lo que se dijo, el estado y la tarea siguiente.", "El acceso del agente sigue los roles de la cuenta del negocio. Esta página no crea un modelo nuevo de permisos."]],
      "pt-BR": ["Agentes humanos para leads e acompanhamento | BizUply", "Os agentes desta página são pessoas, não um chatbot. Eles fazem o acompanhamento definido de leads, dados e horários segundo o serviço que foi de fato contratado. Não há promessa de taxa de resposta nem de venda.", "Agentes", "Quando o negócio precisa de uma pessoa para continuar a consulta", "Um formulário não encerra toda consulta. Às vezes é preciso ligar, esclarecer ou marcar um horário. O serviço de agentes é essa camada humana, dentro dos limites do plano contratado.", ["Uma pessoa na consulta", "O agente trabalha o lead que o negócio atribuiu: lê o que chegou, pergunta o que falta e escreve o resultado na ficha.", "Esta página não descreve um chatbot. Se outra tela mencionar um assistente, é outra ferramenta."], ["Acompanhamento enquanto a consulta ainda está viva", "O trabalho é o próximo contato, não uma promessa de que a pessoa compre. O agente usa os mesmos status que o CRM já tem, para a equipe ver se houve contato.", "Nesta página não há taxa de conversão publicada, e não se deve deduzir uma."], ["Horários, quando o serviço os inclui", "Se o serviço contratado inclui marcar um horário, o agente pode colocá-lo no calendário que a conta já usa. Se o serviço não inclui isso, esta página não acrescenta.", "O alcance atual é o que a página de preços e o contrato dizem. Esta página não inventa um preço de pacote."], ["O registro fica no CRM", "Uma ligação que não é escrita desaparece. O sentido do serviço é o resultado ficar no lead: o que foi dito, o status e a tarefa seguinte.", "O acesso do agente segue os papéis da conta do negócio. Esta página não cria um modelo novo de permissões."]],
      ar: ["مندوبون بشريون للمتابعة مع العملاء المحتملين | BizUply", "المندوبون في هذه الصفحة أشخاص، وليسوا روبوت محادثة. يعالجون متابعة محددة للعملاء المحتملين والتفاصيل والمواعيد وفق الخدمة التي اشتُريت فعلاً. لا يُوعد بمعدل رد أو معدل بيع.", "المندوبون", "حين يحتاج النشاط إلى شخص يكمل الاستفسار", "لا يُنهي النموذج كل استفسار. أحياناً يلزم الاتصال أو التوضيح أو تحديد وقت. خدمة المندوبين هي هذه الطبقة البشرية، ضمن حدود الخطة المشتراة.", ["شخص على الاستفسار", "يعمل المندوب على العميل المحتمل الذي عيّنه النشاط: يقرأ ما وصل، ويسأل عما ينقص، ويكتب النتيجة على السجل.", "لا تصف هذه الصفحة روبوت محادثة. إذا ذكرت شاشة أخرى مساعداً، فتلك أداة أخرى."], ["متابعة ما دام الاستفسار قائماً", "العمل هو الاتصال التالي، وليس وعداً بأن الشخص سيشتري. يستخدم المندوب الحالات نفسها الموجودة في CRM، ليرى الفريق إن تم التواصل.", "لا يوجد في هذه الصفحة معدل تحويل منشور، ولا ينبغي استنتاج واحد."], ["مواعيد، حين تشملها الخدمة", "إذا كانت الخدمة المشتراة تشمل تحديد موعد، يستطيع المندوب وضعه على التقويم الذي يستخدمه الحساب. إذا لم تشمل الخدمة ذلك، لا تضيفه هذه الصفحة.", "النطاق الحالي هو ما تقوله صفحة الأسعار والاتفاق. لا تخترع هذه الصفحة سعر باقة."], ["يبقى التوثيق في CRM", "مكالمة لا تُكتب تختفي. معنى الخدمة أن تُسجَّل النتيجة على العميل المحتمل: ما قيل، والحالة، والمهمة التالية.", "يتبع وصول المندوب الأدوار في حساب النشاط. لا تنشئ هذه الصفحة نموذج صلاحيات جديداً."]],
    }[locale];
    const [title, description, crumb, h1, lede, ...sections] = copy;
    const faq = {
      en: [["What is the human-agent service?", "People doing a defined job on leads: follow-up, missing details, and meetings when the purchased service includes them."], ["Do the agents replace the business team?", "Not necessarily. The service can cover a defined slice of the follow-up. The business keeps the relationship and the decisions."], ["Can they book appointments?", "Only when the purchased service and the account include appointments. This page does not add booking by itself."], ["Is a sale guaranteed?", "No. There is no promised reply rate, conversion rate or revenue."]],
      he: [["מהו שירות הנציגים?", "אנשים שמבצעים עבודה מוגדרת על לידים: המשך טיפול, פרטים חסרים, ופגישות כשהשירות שנרכש כולל אותן."], ["האם הנציגים מחליפים את צוות העסק?", "לא בהכרח. השירות יכול לכסות חלק מוגדר מהמעקב. העסק נשאר עם הקשר ועם ההחלטות."], ["האם הם יכולים לקבוע תורים?", "רק כשהשירות שנרכש והחשבון כוללים תורים. העמוד הזה לא מוסיף זימון מעצמו."], ["האם מובטחת עסקה?", "לא. אין שיעור מענה, שיעור המרה או הכנסה מובטחים."]],
      es: [["¿Qué es el servicio de agentes humanos?", "Personas que hacen un trabajo definido sobre leads: seguimiento, datos que faltan y citas cuando el servicio comprado las incluye."], ["¿Los agentes sustituyen al equipo del negocio?", "No necesariamente. El servicio puede cubrir una parte definida del seguimiento. El negocio conserva la relación y las decisiones."], ["¿Pueden reservar citas?", "Solo cuando el servicio comprado y la cuenta incluyen citas. Esta página no añade la reserva por sí sola."], ["¿Se garantiza una venta?", "No. No hay una tasa de respuesta, de conversión ni un ingreso prometidos."]],
      "pt-BR": [["O que é o serviço de agentes humanos?", "Pessoas que fazem um trabalho definido sobre leads: acompanhamento, dados que faltam e horários quando o serviço contratado os inclui."], ["Os agentes substituem a equipe do negócio?", "Não necessariamente. O serviço pode cobrir uma parte definida do acompanhamento. O negócio fica com o relacionamento e com as decisões."], ["Eles podem marcar horários?", "Somente quando o serviço contratado e a conta incluem agenda. Esta página não acrescenta a reserva por si só."], ["Uma venda é garantida?", "Não. Não há taxa de resposta, taxa de conversão nem receita prometida."]],
      ar: [["ما هي خدمة المندوبين البشريين؟", "أشخاص يؤدون عملاً محدداً على العملاء المحتملين: متابعة، وتفاصيل ناقصة، ومواعيد حين تشملها الخدمة المشتراة."], ["هل يحل المندوبون محل فريق النشاط؟", "ليس بالضرورة. يمكن للخدمة أن تغطي جزءاً محدداً من المتابعة. يبقى النشاط صاحب العلاقة والقرارات."], ["هل يستطيعون حجز مواعيد؟", "فقط حين تشمل الخدمة المشتراة والحساب المواعيد. لا تضيف هذه الصفحة الحجز من تلقاء نفسها."], ["هل تُضمن صفقة؟", "لا. لا يوجد معدل رد أو معدل تحويل أو إيراد موعود."]],
    }[locale];
    return story(title, description, crumb, h1, lede, sections, faq, links);
  }),
  "/collaborations": five((locale, links) => {
    const copy = {
      en: ["Business collaborations and opportunities | BizUply", "BizUply gives businesses a place to find other businesses, post an opportunity and exchange a proposal. Statuses are pending, approved or declined. BizUply does not guarantee a partner, a customer or revenue, and it does not set the commercial terms between the two businesses.", "Collaborations", "A place to explore a working relationship with another business", "Two businesses sometimes fit because one has the work and the other has a skill, a room or an audience. BizUply is the workspace for finding that conversation. The deal, if there is one, is between those businesses.", ["Finding a business that adds something", "You can look through businesses by the field they publish on their profile. A match on the screen is a place to start a conversation, not a recommendation and not a verified partnership.", "The examples people imagine — a designer and a marketer, an agency and a photographer — are illustrations. They are not records of deals inside BizUply."], ["An opportunity with a shape", "An opportunity can carry a title, a description, what is needed, what is offered, an optional budget and an expiry date. Those fields describe the invitation. They do not create a contract.", "A proposal then sits in one of three statuses: pending, approved or declined."], ["The conversation stays in the workspace", "Text chat is there so the two sides can talk without leaving the record of the opportunity. BizUply does not join that conversation as a party to the commercial terms.", "If money moves between the businesses, that movement is theirs. Customer billing inside BizUply is a different system."], ["A relationship can stay, or it can end", "An approved proposal is a status in the product. It is not a guarantee of work next month. Either business can decline, and a customer who stops paying their own BizUply plan is a separate event from this collaboration.", "Collaborations are included in the business plan, at $99 per month or $990 per year. They are not part of CRM only."]],
      he: ["שיתופי פעולה עסקיים והזדמנויות לעסקים | BizUply", "BizUply נותנת לעסקים מקום למצוא עסקים אחרים, לפרסם הזדמנות ולהחליף הצעה. הסטטוסים הם ממתין, אושר או נדחה. BizUply לא מבטיחה שותף, לקוח או הכנסה, והיא לא קובעת את התנאים המסחריים בין שני העסקים.", "שיתופי פעולה", "מקום לבחון קשר עבודה עם עסק אחר", "לפעמים שני עסקים מתאימים כי לאחד יש את העבודה ולשני יש מיומנות, מקום או קהל. BizUply היא סביבת העבודה שבה מתחילים את השיחה הזו. העסקה, אם תהיה, היא בין העסקים עצמם.", ["מציאת עסק שמוסיף משהו", "אפשר לעיין בעסקים לפי התחום שהם מפרסמים בפרופיל. התאמה על המסך היא מקום להתחיל שיחה, לא המלצה ולא שותפות מאומתת.", "הדוגמאות שאנשים מדמיינים — מעצב ומשווק, סוכנות וצלם — הן המחשות. הן לא תיעוד של עסקאות בתוך BizUply."], ["הזדמנות עם צורה", "להזדמנות יכולים להיות כותרת, תיאור, מה צריך, מה מוצע, תקציב אופציונלי ותאריך תפוגה. השדות האלה מתארים את ההזמנה. הם לא יוצרים חוזה.", "הצעה יושבת אחר כך באחד משלושה סטטוסים: ממתין, אושר או נדחה."], ["השיחה נשארת בסביבת העבודה", "יש צ'אט טקסט כדי ששני הצדדים יוכלו לדבר בלי לצאת מתיעוד ההזדמנות. BizUply לא נכנסת לשיחה הזו כצד לתנאים המסחריים.", "אם כסף עובר בין העסקים, זו תנועה שלהם. החיוב של לקוחות בתוך BizUply הוא מערכת אחרת."], ["קשר יכול להישאר, או להסתיים", "הצעה שאושרה היא סטטוס במוצר. היא לא ערובה לעבודה בחודש הבא. כל עסק יכול לדחות, ולקוח שמפסיק לשלם על המסלול שלו ב־BizUply הוא אירוע נפרד מהשיתוף הזה.", "שיתופי פעולה כלולים בחבילה העסקית, ב־99 דולר לחודש או 990 דולר לשנה. הם לא חלק מ־CRM בלבד."]],
      es: ["Colaboraciones de negocio y oportunidades | BizUply", "BizUply ofrece un lugar para encontrar otros negocios, publicar una oportunidad e intercambiar una propuesta. Los estados son pendiente, aprobada o rechazada. BizUply no garantiza un socio, un cliente ni ingresos, y no fija las condiciones comerciales entre los dos negocios.", "Colaboraciones", "Un lugar para explorar una relación de trabajo con otro negocio", "A veces dos negocios encajan porque uno tiene el trabajo y el otro una habilidad, un espacio o un público. BizUply es el espacio donde empieza esa conversación. El acuerdo, si lo hay, es entre esos negocios.", ["Encontrar un negocio que aporta algo", "Se pueden revisar negocios según el campo que publican en su perfil. Una coincidencia en pantalla es un lugar para empezar a hablar, no una recomendación ni una sociedad verificada.", "Los ejemplos que la gente imagina — un diseñador y un especialista en marketing, una agencia y un fotógrafo — son ilustraciones. No son registros de acuerdos dentro de BizUply."], ["Una oportunidad con forma", "Una oportunidad puede llevar título, descripción, qué se necesita, qué se ofrece, un presupuesto opcional y una fecha de vencimiento. Esos campos describen la invitación. No crean un contrato.", "Después la propuesta queda en uno de tres estados: pendiente, aprobada o rechazada."], ["La conversación se queda en el espacio de trabajo", "Hay un chat de texto para que las dos partes hablen sin salir del registro de la oportunidad. BizUply no entra en esa conversación como parte de las condiciones comerciales.", "Si el dinero se mueve entre los negocios, ese movimiento es de ellos. La facturación de clientes dentro de BizUply es otro sistema."], ["Una relación puede quedarse, o terminar", "Una propuesta aprobada es un estado en el producto. No es una garantía de trabajo el mes que viene. Cualquiera de los dos negocios puede rechazar, y un cliente que deja de pagar su propio plan de BizUply es un hecho distinto de esta colaboración.", "Las colaboraciones están incluidas en el plan de negocio, a 99 dólares al mes o 990 al año. No forman parte de CRM solo."]],
      "pt-BR": ["Colaborações de negócio e oportunidades | BizUply", "A BizUply oferece um lugar para encontrar outros negócios, publicar uma oportunidade e trocar uma proposta. Os status são pendente, aprovada ou recusada. A BizUply não garante um parceiro, um cliente nem receita, e não define as condições comerciais entre os dois negócios.", "Colaborações", "Um lugar para explorar uma relação de trabalho com outro negócio", "Às vezes dois negócios combinam porque um tem o trabalho e o outro tem uma habilidade, um espaço ou um público. A BizUply é o espaço em que essa conversa começa. O acordo, se existir, é entre esses negócios.", ["Encontrar um negócio que acrescenta algo", "Dá para ver negócios pelo campo que eles publicam no perfil. Uma combinação na tela é um lugar para começar a conversa, não uma recomendação nem uma sociedade verificada.", "Os exemplos que as pessoas imaginam — um designer e um profissional de marketing, uma agência e um fotógrafo — são ilustrações. Não são registros de acordos dentro da BizUply."], ["Uma oportunidade com forma", "Uma oportunidade pode ter título, descrição, o que é preciso, o que é oferecido, um orçamento opcional e uma data de validade. Esses campos descrevem o convite. Eles não criam um contrato.", "Depois a proposta fica em um de três status: pendente, aprovada ou recusada."], ["A conversa fica no espaço de trabalho", "Há um chat de texto para os dois lados falarem sem sair do registro da oportunidade. A BizUply não entra nessa conversa como parte das condições comerciais.", "Se o dinheiro se move entre os negócios, esse movimento é deles. A cobrança de clientes dentro da BizUply é outro sistema."], ["Uma relação pode ficar, ou pode acabar", "Uma proposta aprovada é um status no produto. Não é garantia de trabalho no mês que vem. Qualquer um dos negócios pode recusar, e um cliente que deixa de pagar o próprio plano da BizUply é um fato separado desta colaboração.", "As colaborações estão incluídas no plano de negócios, a 99 dólares por mês ou 990 por ano. Não fazem parte do CRM sozinho."]],
      ar: ["تعاون تجاري وفرص للأعمال | BizUply", "توفّر BizUply مكاناً للعثور على أعمال أخرى، ونشر فرصة، وتبادل عرض. الحالات هي قيد الانتظار أو موافق عليه أو مرفوض. لا تضمن BizUply شريكاً أو عميلاً أو إيراداً، ولا تحدّد الشروط التجارية بين العملين.", "التعاون", "مكان لاستكشاف علاقة عمل مع نشاط آخر", "أحياناً يتلاءم نشاطان لأن لدى أحدهما العمل ولدى الآخر مهارة أو مكاناً أو جمهوراً. BizUply هي مساحة بدء هذه المحادثة. الصفقة، إن وُجدت، تكون بين هذين النشاطين.", ["العثور على نشاط يضيف شيئاً", "يمكن استعراض الأنشطة حسب المجال الذي ينشرونه في الملف. التطابق على الشاشة مكان لبدء حديث، وليس توصية ولا شراكة موثّقة.", "الأمثلة التي يتخيّلها الناس — مصمّم ومسوّق، وكالة ومصوّر — توضيحات. ليست سجلات صفقات داخل BizUply."], ["فرصة ذات شكل", "يمكن للفرصة أن تحمل عنواناً ووصفاً وما هو مطلوب وما يُعرض وميزانية اختيارية وتاريخ انتهاء. تصف هذه الحقول الدعوة. لا تنشئ عقداً.", "بعد ذلك يبقى العرض في واحدة من ثلاث حالات: قيد الانتظار، أو موافق عليه، أو مرفوض."], ["تبقى المحادثة في مساحة العمل", "توجد دردشة نصية ليتحدث الطرفان من دون مغادرة سجل الفرصة. لا تدخل BizUply هذه المحادثة كطرف في الشروط التجارية.", "إذا انتقل مال بين النشاطين فهذه حركتهما. فوترة العملاء داخل BizUply نظام آخر."], ["قد تبقى العلاقة، أو تنتهي", "العرض الموافق عليه حالة في المنتج. ليس ضماناً لعمل في الشهر القادم. يستطيع أي من النشاطين الرفض، والعميل الذي يتوقف عن دفع خطته في BizUply حدث منفصل عن هذا التعاون.", "التعاون مشمول في الخطة التجارية، بسعر 99 دولاراً شهرياً أو 990 سنوياً. ليس جزءاً من CRM وحده."]],
    }[locale];
    const [title, description, crumb, h1, lede, ...sections] = copy;
    const faq = {
      en: [["What is a business collaboration here?", "Two or more businesses using BizUply to explore a piece of work together: an opportunity, a proposal and a conversation."], ["Which businesses can take part?", "Businesses with a profile on the platform. A shared field on the profile is a starting point, not proof that the work will fit."], ["Does every collaboration involve a fee inside BizUply?", "No. The commercial terms between the two businesses are theirs. Collaborations as a product are part of the business plan. CRM only does not include them."], ["Is BizUply a party to the deal?", "No. BizUply provides the workspace and the statuses. It does not set the price between the businesses and it does not guarantee that work will happen."]],
      he: [["מהו שיתוף פעולה עסקי כאן?", "שני עסקים או יותר שמשתמשים ב־BizUply כדי לבחון עבודה משותפת: הזדמנות, הצעה ושיחה."], ["אילו עסקים יכולים להשתתף?", "עסקים עם פרופיל בפלטפורמה. תחום משותף בפרופיל הוא נקודת התחלה, לא הוכחה שהעבודה תתאים."], ["האם כל שיתוף מחייב תשלום בתוך BizUply?", "לא. התנאים המסחריים בין שני העסקים הם שלהם. שיתופי פעולה כמוצר הם חלק מהחבילה העסקית. CRM בלבד לא כולל אותם."], ["האם BizUply צד לעסקה?", "לא. BizUply מספקת את סביבת העבודה ואת הסטטוסים. היא לא קובעת את המחיר בין העסקים ולא מבטיחה שהעבודה תתקיים."]],
      es: [["¿Qué es una colaboración de negocio aquí?", "Dos o más negocios que usan BizUply para explorar un trabajo juntos: una oportunidad, una propuesta y una conversación."], ["¿Qué negocios pueden participar?", "Negocios con un perfil en la plataforma. Un campo compartido en el perfil es un punto de partida, no una prueba de que el trabajo encajará."], ["¿Toda colaboración implica un pago dentro de BizUply?", "No. Las condiciones comerciales entre los dos negocios son de ellos. Las colaboraciones como producto forman parte del plan de negocio. CRM solo no las incluye."], ["¿BizUply es parte del acuerdo?", "No. BizUply aporta el espacio de trabajo y los estados. No fija el precio entre los negocios y no garantiza que el trabajo se haga."]],
      "pt-BR": [["O que é uma colaboração de negócio aqui?", "Dois ou mais negócios que usam a BizUply para explorar um trabalho juntos: uma oportunidade, uma proposta e uma conversa."], ["Quais negócios podem participar?", "Negócios com um perfil na plataforma. Um campo em comum no perfil é um ponto de partida, não uma prova de que o trabalho vai encaixar."], ["Toda colaboração envolve um pagamento dentro da BizUply?", "Não. As condições comerciais entre os dois negócios são deles. Colaborações como produto fazem parte do plano de negócios. O CRM sozinho não as inclui."], ["A BizUply é parte do acordo?", "Não. A BizUply fornece o espaço de trabalho e os status. Ela não define o preço entre os negócios e não garante que o trabalho aconteça."]],
      ar: [["ما هو التعاون التجاري هنا؟", "نشاطان أو أكثر يستخدمون BizUply لاستكشاف عمل مشترك: فرصة، وعرض، ومحادثة."], ["أي الأنشطة تستطيع المشاركة؟", "أنشطة لديها ملف على المنصة. مجال مشترك في الملف نقطة بداية، وليس دليلاً على أن العمل سيناسب."], ["هل كل تعاون يلزم بدفع داخل BizUply؟", "لا. الشروط التجارية بين النشاطين تخصهما. التعاون كمنتج جزء من الخطة التجارية. CRM وحده لا يشمله."], ["هل BizUply طرف في الصفقة؟", "لا. توفّر BizUply مساحة العمل والحالات. لا تحدّد السعر بين النشاطين ولا تضمن أن العمل سيتم."]],
    }[locale];
    return story(title, description, crumb, h1, lede, sections, faq, links);
  }),
};

void link;
